const mapSvg = (label, content) => `
<svg role="img" aria-label="${label}" viewBox="0 0 240 150" xmlns="http://www.w3.org/2000/svg">
  <rect width="240" height="150" fill="${SEA}"/>
  ${content}
</svg>`;

